def ping_from_host(host_name, targets):
    """Ping a list of target IPs from a host. Returns dict of target -> success."""
    params = {k: v for k, v in HOSTS[host_name].items() if k not in ("lab_ip", "guest")}
    results = {}
    try:
        conn = ConnectHandler(**params, timeout=30, session_timeout=120)
        for target_name, target_ip in targets:
            try:
                out = conn.send_command(f"ping -c 2 -W 3 {target_ip}", read_timeout=15)
                success = "0% packet loss" in out or "1 packets received" in out or "2 packets received" in out
                results[f"{host_name} -> {target_name} ({target_ip})"] = success
            except Exception as e:
                results[f"{host_name} -> {target_name} ({target_ip})"] = False
        conn.disconnect()
    except Exception as e:
        for target_name, target_ip in targets:
            results[f"{host_name} -> {target_name} ({target_ip})"] = False
    return results


